import numpy as np
from PIL import Image
for folder in ['after_grasp_close','j1_plus','j4_plus']:
 for cam in ['top','front','side']:
  rgb=np.array(Image.open(f'/app/output/{folder}/last/{cam}.jpg'))
  dep=np.load(f'/app/output/{folder}/depth_{cam}.npy')[0]
  if cam=='top': roi=(135,78,180,128)
  elif cam=='front': roi=(135,70,180,130)
  else: roi=(105,85,160,145)
  x0,y0,x1,y1=roi; sl=rgb[y0:y1,x0:x1];d=dep[y0:y1,x0:x1]
  nongreen=~((sl[:,:,1]>sl[:,:,0]*1.4)&(sl[:,:,1]>sl[:,:,2]*1.4)&(sl[:,:,1]>100))
  m=(d<0.98)&nongreen
  yy,xx=np.where(m)
  print(folder,cam,'cnt',len(xx),'cent',((x0+xx.mean(),y0+yy.mean()) if len(xx) else None),'dmed',np.median(d[m]) if len(xx) else None)
